///////////////////////////////////////////////////////////////////////////////////////////////////
// module : mcu_core
///////////////////////////////////////////////////////////////////////////////////////////////////

`timescale 1ps / 1ps

module ph1_ddrphy_mcu_core #(
    parameter  MCU_TCM_INIT = ""
)(
    input         i_clk         ,
    input         i_rst         ,

// local memory bus
    output        o_apb_psel    ,
    output        o_apb_penable ,
    output        o_apb_pwrite  ,
    output [31:0] o_apb_paddr   ,
    output [31:0] o_apb_pwdata  ,
    input  [31:0] i_apb_prdata  ,
    input         i_apb_pready
);

///////////////////////////////////////////////////////////////////////////////////////////////////
// Local Parameters
///////////////////////////////////////////////////////////////////////////////////////////////////
localparam [31:0] RESET_VECTOR = 32'h0000_0000;


///////////////////////////////////////////////////////////////////////////////////////////////////
// Internal Signals
///////////////////////////////////////////////////////////////////////////////////////////////////
wire         rst_done;
reg   [ 1:0] rst_r   ;
wire         rst_int ;

wire         pc_vld;
wire  [31:0] PC;

wire  [31:0] pc_jump;
wire         pc_jump_vld;

wire         instr_vld     ;
wire  [31:0] instr_code    ;

wire  [ 4:0] instr_rs1_idx ;
wire  [ 4:0] instr_rs2_idx ;
wire  [11:0] instr_csr_idx ;
wire  [31:0] instr_rs1     ;
wire  [31:0] instr_rs2     ;
wire  [ 4:0] instr_rd_idx  ;
wire  [31:0] instr_rd_data ;
wire         instr_rd_vld  ;

wire  [ 4:0] instr_shamt   ;
wire  [31:0] instr_imm     ;

wire         instr_rvc_en   ;

wire         instr_op_system;
wire         instr_op_load  ;
wire         instr_op_store ;

wire         instr_lui    ;
wire         instr_auipc  ;
wire         instr_jal    ;
wire         instr_jalr   ;
wire         instr_beq    ;
wire         instr_bne    ;
wire         instr_blt    ;
wire         instr_bge    ;
wire         instr_bltu   ;
wire         instr_bgeu   ;
wire         instr_lb     ;
wire         instr_lh     ;
wire         instr_lw     ;
wire         instr_lbu    ;
wire         instr_lhu    ;
wire         instr_sb     ;
wire         instr_sh     ;
wire         instr_sw     ;
wire         instr_addi   ;
wire         instr_slti   ;
wire         instr_sltiu  ;
wire         instr_xori   ;
wire         instr_ori    ;
wire         instr_andi   ;
wire         instr_slli   ;
wire         instr_srli   ;
wire         instr_srai   ;
wire         instr_add    ;
wire         instr_sub    ;
wire         instr_sll    ;
wire         instr_slt    ;
wire         instr_sltu   ;
wire         instr_xor    ;
wire         instr_srl    ;
wire         instr_sra    ;
wire         instr_or     ;
wire         instr_and    ;
wire         instr_fence  ;
wire         instr_ecall  ;
wire         instr_ebreak ;

wire         instr_csrrw  ;
wire         instr_csrrc  ;
wire         instr_csrrs  ;
wire         instr_csrrwi ;
wire         instr_csrrci ;
wire         instr_csrrsi ;

wire         csr_rd_vld   ;
wire  [31:0] csr_rd_data  ;

wire         mem_wr_done  ;
wire         mem_rd_vld   ;
wire  [31:0] mem_rd_data  ;

wire         mem_wen      ;
wire  [31:0] mem_waddr    ;
wire  [31:0] mem_wdata    ;
wire  [ 3:0] mem_wmask    ;
wire         mem_wresp    ;
wire         mem_ren      ;
wire  [31:0] mem_raddr    ;
wire  [31:0] mem_rdata    ;
wire         mem_rvld     ;

wire         tcm_wen      ;
wire  [31:0] tcm_waddr    ;
wire  [31:0] tcm_wdata    ;
wire  [ 3:0] tcm_wmask    ;
wire         tcm_ren      ;
wire  [31:0] tcm_raddr    ;
wire  [31:0] tcm_rdata    ;
wire         tcm_rvld     ;

wire         pc2tcm_ren   ;
reg          pc2tcm_ren_r ;
wire  [31:0] pc2tcm_raddr ;
reg   [31:0] pc2tcm_rdata ;
reg          pc2tcm_rvld  ;

wire         mem2tcm_wen  ;
wire  [31:0] mem2tcm_waddr;
wire  [31:0] mem2tcm_wdata;
wire  [ 3:0] mem2tcm_wmask;
wire         mem2tcm_ren  ;
reg          mem2tcm_ren_r;
wire  [31:0] mem2tcm_raddr;
reg   [31:0] mem2tcm_rdata;
reg          mem2tcm_rvld ;

///////////////////////////////////////////////////////////////////////////////////////////////////
// Reset Generate
///////////////////////////////////////////////////////////////////////////////////////////////////
always @ (posedge i_clk or posedge i_rst)
begin
    if (i_rst == 1'b1)
        rst_r <= 2'b11;
    else if (rst_done)
        rst_r <= {rst_r[0], 1'b0};
end

assign rst_int = rst_r[1];

///////////////////////////////////////////////////////////////////////////////////////////////////
// Promgram Counter
///////////////////////////////////////////////////////////////////////////////////////////////////
ph1_ddrphy_mcu_core_pc #(
    .RESET_VECTOR ( RESET_VECTOR   )
) u_mcu_core_pc (
    .i_clk        ( i_clk          ),
    .i_rst        ( rst_int        ),

    .i_rvc_en     ( instr_rvc_en   ),

    .i_op_load    ( instr_op_load  ),
    .i_op_store   ( instr_op_store ),

    .i_load_done  ( mem_rd_vld     ),
    .i_store_done ( mem_wr_done    ),

    .i_jump_vld   ( pc_jump_vld    ),
    .i_jump       ( pc_jump        ),

    .o_tcm_ren    ( pc2tcm_ren     ),
    .o_tcm_raddr  ( pc2tcm_raddr   ),
    .i_tcm_rdata  ( pc2tcm_rdata   ),
    .i_tcm_rvld   ( pc2tcm_rvld    ),

    .o_instr_vld  ( instr_vld      ),
    .o_instr      ( instr_code     ),

    .o_pc_vld     ( pc_vld         ),
    .o_pc         ( PC             )
);

///////////////////////////////////////////////////////////////////////////////////////////////////
// PC to Memory
///////////////////////////////////////////////////////////////////////////////////////////////////
ph1_ddrphy_mcu_core_tcm #(
    .MCU_TCM_INIT ( MCU_TCM_INIT )
) u_mcu_core_tcm (
    .i_clk       ( i_clk      ),
    .i_rst       ( rst_int    ),

    .i_tcm_wen   ( tcm_wen    ),
    .i_tcm_waddr ( tcm_waddr  ), // 4-byte aligned
    .i_tcm_wdata ( tcm_wdata  ),
    .i_tcm_wmask ( tcm_wmask  ),

    .i_tcm_ren   ( tcm_ren    ),
    .i_tcm_raddr ( tcm_raddr  ), // 4-byte aligned
    .o_tcm_rvld  ( tcm_rvld   ),
    .o_tcm_rdata ( tcm_rdata  )
);

assign tcm_wen   = mem2tcm_wen  ;
assign tcm_waddr = mem2tcm_waddr;
assign tcm_wdata = mem2tcm_wdata;
assign tcm_wmask = mem2tcm_wmask;

assign tcm_ren   = pc2tcm_ren | mem2tcm_ren;
assign tcm_raddr = pc2tcm_ren ? pc2tcm_raddr : mem2tcm_ren ? mem2tcm_raddr : pc2tcm_raddr;
//assign pc2tcm_rvld  = tcm_rvld & pc2tcm_ren_r;
//assign pc2tcm_rdata = tcm_rdata;

always @ (posedge i_clk) begin
    if (rst_int == 1'b1) begin
       mem2tcm_ren_r <= 1'b0;
        pc2tcm_ren_r <= 1'b0;
    end else begin
       mem2tcm_ren_r <= mem2tcm_ren;
        pc2tcm_ren_r <=  pc2tcm_ren;
    end
end

always @ (posedge i_clk) begin
    if (rst_int == 1'b1) begin
       pc2tcm_rvld  <=  1'b0;
       pc2tcm_rdata <= 32'h0;
    end else if (pc2tcm_ren_r) begin
       pc2tcm_rvld  <= tcm_rvld;
       pc2tcm_rdata <= tcm_rdata;
    end else begin
       pc2tcm_rvld  <= 1'b0;
    end
end


always @ (posedge i_clk) begin
    if (rst_int == 1'b1) begin
       mem2tcm_rvld  <=  1'b0;
       mem2tcm_rdata <= 32'h0;
    end else if (mem2tcm_ren_r) begin
       mem2tcm_rvld  <= 1'b1;
       mem2tcm_rdata <= tcm_rdata;
    end else begin
       mem2tcm_rvld  <= 1'b0;
    end
end

